    if (INTENT_SUMMARY_NON_POLICY_PREFIX_PATTERN.test(line)) {
      return false;
    }
    return !INTENT_SUMMARY_NON_POLICY_LINE_PATTERN.test(line);
  };

  const normalizeList = (input: unknown): string[] =>
    Array.isArray(input)
      ? Array.from(
          new Set(
            input
              .filter((item): item is string => typeof item === 'string')
