/**
 * Produces review intent from raw session prompts, preferring the model-backed pre-pass and
 * falling back to heuristic extraction when no reliable structured summary is available.
 */
export async function summarizeReviewIntentPolicy(
  env: Env,
  input: {
    rawSessionPrompts: string;
    intentSessionContext?: string[];
    openrouterApiKey?: string | null;
    intentSummaryModel?: string | null;
  }
): Promise<ReviewSessionIntentSummary | null> {
  const rawSessionPrompts = input.rawSessionPrompts.trim();
  const intentSessionContext = uniqueStrings(
    Array.isArray(input.intentSessionContext)
      ? input.intentSessionContext.filter((item): item is string => typeof item === 'string').map((item) => item.trim())
      : []
  );
  if (!rawSessionPrompts) {
    return null;
  }
  const modelSummary = await runIntentSummarizationPrePass(env, rawSessionPrompts, {
    openrouterApiKey: input.openrouterApiKey,
    intentSummaryModel: input.intentSummaryModel,
  });
  return modelSummary ?? deriveIntentSummaryFallback(rawSessionPrompts, intentSessionContext);
}

import type { ReviewAnalysisOutputV2 } from '../../types.js';
import { validateAndNormalizeReviewAnalysisOutputV2 } from '../review-output-v2.js';
import { redactReviewText } from '../review-redaction.js';
import { asRecord, asStringArray, extractJsonObject, stripCodeFences } from './helpers.js';

export interface ReviewAgentIntent {
  goal: string | null;
  constraints: string[];
  decisions: string[];
}

export class ReviewAgentOutputError extends Error {
  code: string;
  details: Record<string, unknown> | null;

  constructor(message: string) {
    super(message);
    this.name = 'ReviewAgentOutputError';
    this.code = 'review_analysis_invalid_output';
    this.details = null;
  }

  withCode(code: string, details?: Record<string, unknown>): ReviewAgentOutputError {
    this.code = code;
    this.details = details ?? null;
    return this;
  }
}

export function normalizeIntent(value: unknown): ReviewAgentIntent | null {
  const record = asRecord(value);
  if (Object.keys(record).length === 0) {
    return null;
  }

  return {
    goal: typeof record.goal === 'string' && record.goal.trim() ? record.goal.trim() : null,
    constraints: asStringArray(record.constraints).map((item) => item.trim()).filter(Boolean),
    decisions: asStringArray(record.decisions).map((item) => item.trim()).filter(Boolean),
  };
}

export function parseJsonOutput(summary: string): unknown {
  try {
    return JSON.parse(extractJsonObject(summary)) as unknown;
  } catch {
    const summaryText = stripCodeFences(summary).trim();
    throw new ReviewAgentOutputError(
      summaryText
        ? `Review agent returned malformed final output: ${summaryText.slice(0, 240)}`
        : 'Review agent returned malformed final output'
    ).withCode('review_analysis_invalid_output');
  }
}

export function validateOutputOrThrow(payload: unknown): { output: ReviewAnalysisOutputV2; dedupedExactCount: number } {
  const validated = validateAndNormalizeReviewAnalysisOutputV2(payload);
  if (!validated.ok) {
    throw new ReviewAgentOutputError('Review agent output does not match required schema').withCode(
      'review_analysis_invalid_output',
      { errors: validated.errors }
    );
  }
  return { output: validated.value, dedupedExactCount: validated.dedupedExactCount };
}

export function extractValidationErrors(error: ReviewAgentOutputError | null): Array<{ path: string; message: string }> {
  if (!error?.details || !Array.isArray(error.details.errors)) {
    return [];
  }
  return error.details.errors
    .map((item) => {
      const record = asRecord(item);
      const path = typeof record.path === 'string' ? record.path : '';
      const message = typeof record.message === 'string' ? record.message : '';
      return path && message ? { path, message } : null;
    })
    .filter((item): item is { path: string; message: string } => Boolean(item))
    .slice(0, 20);
}

export function buildFallbackAnalysisOutput(reason: string): ReviewAnalysisOutputV2 {
  return {
    findings: [],
    summary: `Structured model output was invalid after repair (${reason}); emitted fallback empty findings output.`,
    furtherPassesLowYield: true,
  };
}

export function isGenericProviderCompletionSummary(summary: string): boolean {
  return /completed by .*agent endpoint/i.test(summary.trim());
}

export function sanitizeErrorMessage(input: string, options?: { openrouterApiKey?: string | null }): string {
  let sanitized = redactReviewText(input) ?? '';
  const openrouterApiKey = options?.openrouterApiKey?.trim();
  if (openrouterApiKey) {
    sanitized = sanitized.split(openrouterApiKey).join('[REDACTED_OPENROUTER_API_KEY]');
  }
  return sanitized;
}

export function isWorkerToWorkerFetchRestriction(status: number, responseBody: string): boolean {
  return status === 404 && /error\s*code\s*:\s*1042/i.test(responseBody);
}

export function isMissingOpenRouterApiKeyError(responseBody: string): boolean {
  if (!responseBody.trim()) {
    return false;
  }
  try {
    const parsed = JSON.parse(responseBody) as Record<string, unknown>;
    const errorCode = typeof parsed.error === 'string' ? parsed.error : '';
    const details = asRecord(parsed.details);
    const detailsMessage = typeof details.message === 'string' ? details.message : '';
    return errorCode === 'missing_openrouter_api_key' || /openrouter_api_key\s+is\s+required/i.test(detailsMessage);
  } catch {
    return /missing_openrouter_api_key|openrouter_api_key\s+is\s+required/i.test(responseBody);
  }
}

export function isTimeoutLikeError(error: unknown): boolean {
  if (!(error instanceof Error)) {
    return false;
  }
  if (error.name === 'AbortError') {
    return true;
  }
  const message = error.message.toLowerCase();
  return message.includes('timeout') || message.includes('timed out') || message.includes('aborted');
}

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

import type { Env, ReviewReport, ReviewRunResponse } from '../types.js';
import {
  appendReviewEvent,
  claimReviewRunForExecution,
  getReviewRun,
  getReviewRunRequestPayload,
  updateReviewRunStatus,
} from './db.js';
import { formatReviewAnalysisError } from './review-analysis.js';
import { ReviewContextAssemblyError } from './review-runner/cochange.js';
import { readOptionalString } from './review-runner/context-helpers.js';
import { assembleReviewContextBootstrap } from './review-runner/context.js';
import { executeReviewRun } from './review-runner/execution.js';
import { finalizeFailedReviewIfCurrent, finalizeSuccessfulReview } from './review-runner/finalization.js';
import { intentSummaryFromApprovedPolicy, runIntentSummarizationPrePass, summarizeReviewIntentPolicy } from './review-runner/intent-summary.js';
import {
  finalizeInlineRetryExhaustion,
  handleUnclaimedReviewRun,
  QueueRetryError,
  scheduleReviewRetryIfCurrent,
  shouldRetryReviewError,
} from './review-runner/retry.js';
import type { ReviewRunExecutionOptions } from './review-runner/shared.js';

export {
  intentSummaryFromApprovedPolicy,
  runIntentSummarizationPrePass,
  summarizeReviewIntentPolicy,
} from './review-runner/intent-summary.js';
export { shouldRetryReviewError } from './review-runner/retry.js';

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

function isManuallyFailedReview(review: ReviewRunResponse | null): boolean {
  return review?.status === 'failed' && review.error?.code === 'review_execution_aborted';
}

async function loadLatestReviewUnlessManuallyFailed(env: Env, reviewId: string): Promise<ReviewRunResponse | null> {
  const latest = await getReviewRun(env.DB, reviewId);
  return isManuallyFailedReview(latest) ? null : latest;
}

function startManualFailAbortMonitor(env: Env, reviewId: string): { signal: AbortSignal; stop: () => void } {
  const controller = new AbortController();
  let stopped = false;
  let polling = false;
  let timer: ReturnType<typeof setInterval> | null = null;

  const stop = (): void => {
    if (stopped) {
      return;
    }
    stopped = true;
    if (timer !== null) {
      clearInterval(timer);
      timer = null;
    }
  };

  const poll = async (): Promise<void> => {
    if (stopped || polling || controller.signal.aborted) {
      return;
    }
    polling = true;
    try {
      const latest = await getReviewRun(env.DB, reviewId);
      if (isManuallyFailedReview(latest)) {
        controller.abort();
        stop();
      }
    } catch {
      // Best-effort polling only; transient read failures must not become unhandled rejections.
    } finally {
      polling = false;
    }
  };

  timer = setInterval(() => {
    void poll();
  }, 250);
  void poll();

  return { signal: controller.signal, stop };
}

/**
 * Claims, executes, persists, and finalizes one review run.
 * This is the main orchestration boundary for review execution and retry scheduling.
 */
export async function processReviewRun(env: Env, reviewId: string, options?: ReviewRunExecutionOptions): Promise<void> {
  const claimed = await claimReviewRunForExecution(env.DB, reviewId);
  if (!claimed) {
    const existing = await getReviewRun(env.DB, reviewId);
    if (existing?.status === 'running') {
      await handleUnclaimedReviewRun(env, reviewId, existing, options?.allowRetryScheduling ?? true);
    }
    return;
  }

  let review: ReviewRunResponse | null = null;
  const manualFailAbortMonitor = startManualFailAbortMonitor(env, reviewId);
  try {
    review = await getReviewRun(env.DB, reviewId);
    if (!review) {
      return;
    }

    const payload = await getReviewRunRequestPayload(env.DB, reviewId);
    if (!payload) {
      await updateReviewRunStatus(env.DB, reviewId, 'failed', {
        errorCode: 'review_not_found',
        errorMessage: 'Review request payload no longer exists',
      });
      await appendReviewEvent(env.DB, {
        reviewId,
        eventType: 'review_failed',
        payload: {
          code: 'review_not_found',
          message: 'Review request payload no longer exists',
        },
      });
      return;
    }

    const reviewContext = await assembleReviewContextBootstrap(env, review, payload, options);
    const report = await executeReviewRun(env, review, payload, reviewContext, {
      ...options,
      abortSignal: manualFailAbortMonitor.signal,
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    await finalizeSuccessfulReview(env, reviewId, payload, report, {
      expectedAttemptCount: review.attemptCount,
      allowRetryScheduling: options?.allowRetryScheduling,
    });
  } catch (error) {
    const message = formatReviewAnalysisError(error, {
      openrouterApiKey: readOptionalString(options?.openrouterApiKey),
    });
    const latest = await loadLatestReviewUnlessManuallyFailed(env, reviewId);
    if (!latest) {
      return;
    }
    const attemptCount = review?.attemptCount ?? latest?.attemptCount ?? 0;

    const allowRetryScheduling = options?.allowRetryScheduling !== false;
    if (allowRetryScheduling && shouldRetryReviewError(error) && attemptCount <= 2) {
      const retryScheduled = await scheduleReviewRetryIfCurrent(env, reviewId, {
        attemptCount,
        message,
        reason: message.slice(0, 500),
      });
      if (retryScheduled) {
        throw new QueueRetryError('Review transient failure; retry requested');
      }
    }

    const contextAssemblyErrorCode = error instanceof ReviewContextAssemblyError ? error.code : null;
    const finalErrorCode = contextAssemblyErrorCode ?? 'review_execution_failed';
    await finalizeFailedReviewIfCurrent(env, reviewId, {
      errorCode: finalErrorCode,
      message,
      contextAssemblyErrorCode,
      expectedAttemptCount: attemptCount,
    });
  } finally {
    manualFailAbortMonitor.stop();
  }
}

/**
 * Repeats inline review execution while the persisted state requests another retry cycle.
 */
export async function runReviewInlineWithRetries(
  env: Env,
  reviewId: string,
  maxCycles = 4,
  options?: ReviewRunExecutionOptions
): Promise<void> {
  for (let cycle = 0; cycle < maxCycles; cycle += 1) {
    try {
      await processReviewRun(env, reviewId, options);
    } catch {
      // Retry scheduling is inferred from persisted status.
    }

    const latest = await getReviewRun(env.DB, reviewId);
    if (!latest) {
      return;
    }
    if (latest.status !== 'queued') {
      return;
    }
    if (latest.error?.code !== 'retry_scheduled') {
      return;
    }
  }

  await finalizeInlineRetryExhaustion(env, reviewId);
}

const DEFAULT_WORKER_URL = 'https://nimbus-worker.ndejesus1227.workers.dev';
const DEFAULT_WORKER_ORIGIN = new URL(DEFAULT_WORKER_URL).origin;
const MISSING_API_KEY_WARNING =
  'NIMBUS_API_KEY is required to use the hosted Nimbus worker. Set it in your env or .env file.';

let hasWarnedMissingHostedApiKey = false;

export function __resetApiClientStateForTests(): void {
  hasWarnedMissingHostedApiKey = false;
}

function readNimbusApiKey(): string | null {
  const value = process.env.NIMBUS_API_KEY;
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function readOpenrouterApiKey(): string | null {
  const value = process.env.OPENROUTER_API_KEY;
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function readReviewGithubToken(): string | null {
  return typeof process.env.REVIEW_CONTEXT_GITHUB_TOKEN === 'string' && process.env.REVIEW_CONTEXT_GITHUB_TOKEN.trim()
    ? process.env.REVIEW_CONTEXT_GITHUB_TOKEN.trim()
    : null;
}

function usesHostedWorker(workerUrl: string): boolean {
  try {
    return new URL(workerUrl).origin === DEFAULT_WORKER_ORIGIN;
  } catch {
    return false;
  }
}

function maybeWarnMissingApiKey(workerUrl: string, apiKey: string | null): void {
  if (apiKey || hasWarnedMissingHostedApiKey || !usesHostedWorker(workerUrl)) {
    return;
  }
  hasWarnedMissingHostedApiKey = true;
  process.stderr.write(`${MISSING_API_KEY_WARNING}\n`);
}

function toHeaderRecord(headers?: RequestInit['headers']): Record<string, string> {
  const requestHeaders: Record<string, string> = {};
  if (headers instanceof Headers) {
    headers.forEach((value, key) => {
      requestHeaders[key] = value;
    });
  } else if (Array.isArray(headers)) {
    for (const [key, value] of headers) {
      requestHeaders[key] = value;
    }
  } else if (headers) {
    Object.assign(requestHeaders, headers as Record<string, string>);
  }
  return requestHeaders;
}

function withAuthHeaders(workerUrl: string, headers?: RequestInit['headers']): Record<string, string> {
  const requestHeaders = toHeaderRecord(headers);
  const apiKey = readNimbusApiKey();
  if (apiKey) {
    requestHeaders['X-Nimbus-Api-Key'] = apiKey;
  }
  maybeWarnMissingApiKey(workerUrl, apiKey);
  return requestHeaders;
}

export function withReviewHeaders(baseHeaders?: RequestInit['headers']): Record<string, string> {
  const headers = toHeaderRecord(baseHeaders);

  const openrouterApiKey = readOpenrouterApiKey();
  if (openrouterApiKey) {
    headers['X-Openrouter-Api-Key'] = openrouterApiKey;
  }

  const reviewGithubToken = readReviewGithubToken();
  if (reviewGithubToken) {
    headers['X-Review-Github-Token'] = reviewGithubToken;
  }

  return headers;
}

export function getWorkerUrl(): string {
  return process.env.NIMBUS_WORKER_URL || DEFAULT_WORKER_URL;
}

export async function workerFetch(workerUrl: string, url: string, init?: RequestInit): Promise<Response> {
  const headers = withAuthHeaders(workerUrl, init?.headers);
  return fetch(url, {
    ...init,
    headers,
  });
}

export async function workerFetchWithoutAuth(url: string, init?: RequestInit): Promise<Response> {
  return fetch(url, init);
}

export async function throwWorkerError(response: Response, notFoundMessage?: string): Promise<never> {
  if (response.status === 404 && notFoundMessage) {
    throw new Error(notFoundMessage);
  }
  const errorText = await response.text();
  throw new Error(`Worker error (${response.status}): ${errorText}`);
}

